import torch
import torch.nn as nn

class SoftClamp(nn.Module):
    def __init__(self, beta=1.0):
        super().__init__()
        self.beta = beta

    def forward(self, x, lower, upper):
        m = (lower + upper) / 2.0
        h = (upper - lower) / 2.0
        return m + h * torch.tanh(self.beta * (x - m) / h)

class WW_NTBN(nn.Module):
    def __init__(self, risk_aversion=1.0, tc_rate=0.01):
        super().__init__()
        self.gamma = risk_aversion
        self.lam = tc_rate
        self.net = nn.Sequential(
            nn.Linear(2, 16),
            nn.ReLU(),
            nn.Linear(16, 1)
        )
        self.soft_clamp = SoftClamp(beta=1.0)

    def forward(self, prev_hedge, spot, bs_delta, bs_gamma):
        w_ww = ((3.0 * self.lam * (spot**2) * (bs_gamma**2)) / self.gamma) ** (1.0/3.0)
        inputs = torch.stack([spot, bs_gamma], dim=-1)
        multiplier = torch.exp(self.net(inputs).squeeze(-1))
        w = w_ww * multiplier
        lower = bs_delta - w
        upper = bs_delta + w
        return self.soft_clamp(prev_hedge, lower, upper)
